def isNumber(s: str) -> bool:
    s = s.strip()
    if not s:
        return False

    i = 0
    n = len(s)

    # Check for optional sign
    if i < n and (s[i] == '+' or s[i] == '-'):
        i += 1

    # Check digits before decimal point
    has_digit = False
    while i < n and s[i].isdigit():
        has_digit = True
        i += 1

    # Check for decimal point and digits after it
    if i < n and s[i] == '.':
        i += 1
        while i < n and s[i].isdigit():
            has_digit = True
            i += 1

    if not has_digit:
        return False

    # Check for exponent
    if i < n and (s[i] == 'e' or s[i] == 'E'):
        i += 1
        if i < n and (s[i] == '+' or s[i] '-'):
            i += 1

        has_exp_digit = False
        while i < n and s[i].isdigit():
            has_exp_digit = True
            i += 1

        if not has_exp_digit:
            return False

    return i == n
